 function internal(kind:Tab['kind'],title:string,extra:Partial<Tab>={}){const id=crypto.randomUUID();addTab({id,kind,title,...extra})}
 function closeTab(id:string){const current=tabsRef.current;const nt=current.filter(t=>t.id!==id);tabsRef.current=nt;setTabs(nt);const closing=current.find(t=>t.id===id);if(closing?.kind==='site')schedulePersistSiteTabs(nt);if(active===id){const idx=current.findIndex(t=>t.id===id);const fallback=nt[Math.max(0,idx-1)]||nt[idx]||null;setActive(fallback?.id||'home');if(fallback?.kind==='site'&&fallback.url)localStorage.setItem('orbitdesk:last-url',fallback.url);else localStorage.removeItem('orbitdesk:last-url');}}
 async function logout(){await api('/api/auth/logout',{method:'POST'});location.reload()}
